// Turns any form/webhook payload into one clean lead.
// Works with n8n Form, Typeform/Tally/Jotform/Webflow/WordPress webhooks, Zapier/Make, Facebook Lead Ads via Zapier, etc.
const cfg = $('Settings').first().json.config;
const key = (k) => String(k).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

function flatten(obj, into = {}) {
  for (const [k, v] of Object.entries(obj || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v)) flatten(v, into);
    else if (!(key(k) in into)) into[key(k)] = v;
  }
  return into;
}
function pick(data, keys) {
  for (const k of keys) {
    const v = data[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}
function normalizePhone(raw, cc) {
  if (!raw) return '';
  let p = String(raw).replace(/^whatsapp:/i, '').trim();
  const plus = p.startsWith('+') || p.startsWith('00');
  let digits = p.replace(/\D/g, '');
  if (p.startsWith('00')) digits = digits.slice(2);
  if (digits.length < 6) return '';
  if (plus) return '+' + digits;
  const ccDigits = String(cc || '').replace(/\D/g, '');
  if (ccDigits && digits.startsWith(ccDigits) && digits.length > 10) return '+' + digits;
  return '+' + ccDigits + digits.replace(/^0/, '');
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const { event, config, headers, params, query, ...rest } = j;
  const data = flatten(j.body && typeof j.body === 'object' ? j.body : rest);

  let name = pick(data, ['name', 'full_name', 'fullname', 'your_name', 'contact_name']);
  if (!name) name = [pick(data, ['first_name', 'firstname', 'first']), pick(data, ['last_name', 'lastname', 'last'])].filter(Boolean).join(' ');
  let email = pick(data, ['email', 'email_address', 'e_mail', 'your_email', 'mail']).toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) email = '';
  const phone = normalizePhone(pick(data, ['phone', 'phone_number', 'mobile', 'mobile_phone', 'mobile_number', 'tel', 'telephone', 'cell', 'whatsapp']), cfg.default_country_code);
  const message = pick(data, ['message', 'how_can_we_help', 'comments', 'comment', 'notes', 'details', 'enquiry', 'inquiry', 'description', 'question']);
  const source = pick(data, ['source', 'lead_source', 'utm_source', 'form_name', 'formname']) || (j.formMode ? 'Website form (n8n)' : 'Webhook');

  out.push({ json: {
    lead_id: 'L' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase(),
    received_at: new Date().toISOString(),
    name, email, phone, source, message,
    has_contact: Boolean(email || phone),
  }});
}
return out;

