const lead = $('Clean up lead details').item.json;
const cfg = $('Settings').first().json.config;
const ai = $json.output || {};
const score = Math.max(1, Math.min(10, Math.round(Number(ai.score)) || 5));
const hot = Number(cfg.hot_lead_score) || 8;
return { json: {
  lead_id: lead.lead_id,
  received_at: lead.received_at,
  name: lead.name,
  email: lead.email,
  phone: lead.phone,
  source: lead.source,
  message: lead.message,
  score,
  temperature: score >= hot ? 'hot' : score >= 5 ? 'warm' : 'cold',
  summary: ai.summary || '',
  status: 'contacted',
  followups_sent: 0,
  last_contact_at: new Date().toISOString(),
  notes: '',
  sms_message: ai.sms_message || '',
  email_subject: ai.email_subject || 'Thanks for getting in touch',
  email_body: ai.email_body || '',
}};

