// Picks leads that were contacted, haven't replied/booked, and are due their next follow-up.
// Follow-up 1 goes out first_follow_up_after_hours after the lead arrived, follow-up 2 at second_follow_up_after_hours.
const cfg = $('Settings').first().json.config;
const maxFollowUps = Number(cfg.max_follow_ups ?? 2);
const delays = [Number(cfg.first_follow_up_after_hours ?? 24), Number(cfg.second_follow_up_after_hours ?? 72)];
const now = Date.now();
const due = [];
for (const { json: row } of $input.all()) {
  if (String(row.status || '').trim().toLowerCase() !== 'contacted') continue;
  const sent = Number(row.followups_sent) || 0;
  if (sent >= maxFollowUps) continue;
  if (!row.email && !row.phone) continue;
  const received = Date.parse(row.received_at);
  if (Number.isNaN(received)) continue;
  const waitHours = delays[Math.min(sent, delays.length - 1)] + Math.max(0, sent - delays.length + 1) * 48;
  if ((now - received) / 36e5 >= waitHours) due.push({ json: { ...row, followup_number: sent + 1 } });
}
return due.slice(0, 25); // keep each run small

