const row = $('Find leads due a follow-up').item.json;
const cfg = $('Settings').first().json.config;
const ai = $json.output || {};
const n = row.followup_number;
return { json: {
  lead_id: row.lead_id,
  name: row.name,
  email: row.email,
  phone: row.phone,
  followups_sent: n,
  last_contact_at: new Date().toISOString(),
  status: n >= Number(cfg.max_follow_ups ?? 2) ? 'no_response' : 'contacted',
  sms_message: ai.sms_message || '',
  email_subject: ai.email_subject || 'Following up',
  email_body: ai.email_body || '',
}};

// Accepts Cal.com (BOOKING_CREATED), Calendly (invitee.created) or a simple {"email": "..."} webhook.
const b = $json.body || {};
if (b.triggerEvent && b.triggerEvent !== 'BOOKING_CREATED') return [];
if (b.event && b.event !== 'invitee.created') return [];
const p = b.payload || b;
const email = String(p.attendees?.[0]?.email || p.email || p.invitee?.email || '').trim().toLowerCase();
if (!email) return [];
return [{ json: { email, status: 'booked' } }];

// Twilio posts From / Body when a lead texts your number back.
const b = $json.body || {};
const from = String(b.From || '').replace(/^whatsapp:/i, '').trim();
const text = String(b.Body || '').trim();
if (!from) return [];
const optOut = /^(stop|stopall|unsubscribe|cancel|end|quit)$/i.test(text);
return [{ json: { phone: from, reply_text: text, status: optOut ? 'opted_out' : 'replied' } }];
